<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiClient } from '../../services/apiClient'
import { label, safeError } from './enrollment'
import EnrollmentDialog from './EnrollmentDialog.vue'
import './enrollment.css'

const data=ref(null),form=ref(null),detail=ref(null),statusChange=ref(null),busy=ref(false),error=ref(''),notice=ref(''),page=ref(1)
const filters=ref({search:'',course_id:'',curriculum_id:'',status:''})
const curricula=computed(()=>data.value?.curriculums||[])
const filteredCurricula=computed(()=>curricula.value.filter(c=>!filters.value.course_id||Number(c.course_id)===Number(filters.value.course_id)))
const formCurriculum=computed(()=>curricula.value.find(c=>Number(c.id)===Number(form.value?.curriculum_id)))
const prerequisites=computed(()=>data.value?.subjects?.data?.filter(s=>s.id!==form.value?.id&&s.status==='active'&&Number(s.curriculum_id)===Number(form.value?.curriculum_id))||[])
const groups=computed(()=>{const map=new Map();for(const s of data.value?.subjects?.data||[]){const key=s.curriculum_id;if(!map.has(key))map.set(key,{curriculum:s.curriculum,subjects:[]});map.get(key).subjects.push(s)}return [...map.values()]})

async function load(){busy.value=true;error.value='';try{const response=await apiClient.get('/enrollment/academic/subjects',{params:{...filters.value,page:page.value}});data.value=response.data.data}catch(e){error.value=safeError(e)}finally{busy.value=false}}
function blank(){return{curriculum_id:filters.value.curriculum_id||'',semester_id:'',subject_code:'',subject_name:'',year_level:1,units:3,lecture_hours:3,laboratory_hours:0,prerequisite_subject_id:null,status:'active'}}
function openCreate(){form.value=blank();detail.value=null}
function openEdit(subject,assignment=false){form.value={...subject,units:Number(subject.units),assignment};detail.value=null}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const payload={...form.value};delete payload.curriculum;delete payload.semester;delete payload.prerequisite;delete payload.section_subjects_count;delete payload.enrollment_subjects_count;delete payload.assignment;if(payload.id)delete payload.status;for(const key of ['curriculum_id','semester_id','year_level','lecture_hours','laboratory_hours','prerequisite_subject_id'])payload[key]=payload[key]?Number(payload[key]):null;if(payload.id)await apiClient.put(`/enrollment/academic/subjects/${payload.id}`,payload);else await apiClient.post('/enrollment/academic/subjects',payload);form.value=null;notice.value='Subject saved successfully.';await load()}catch(e){error.value=safeError(e)}finally{busy.value=false}}
async function changeStatus(){if(busy.value)return;busy.value=true;error.value='';try{const action=statusChange.value.status==='active'?'archive':'reactivate';await apiClient.post(`/enrollment/academic/subjects/${statusChange.value.id}/${action}`);statusChange.value=null;notice.value=`Subject ${action==='archive'?'archived':'reactivated'} successfully.`;await load()}catch(e){error.value=safeError(e)}finally{busy.value=false}}
function apply(){page.value=1;load()}
onMounted(load)
</script>

<template><section class="enrollment-workspace subject-management"><header class="page-header"><p class="page-kicker">Enrollment</p><h1 class="page-title">Subjects</h1><p>Manage the curriculum-specific subject catalog used by Enrollment and Scheduling.</p></header>
<p v-if="error" role="alert">{{ error }} <button :disabled="busy" @click="load">Retry</button></p><p v-if="notice" role="status">{{ notice }}</p><p v-if="busy" role="status">Loading subjects…</p>
<div class="en-actions"><button :disabled="busy" @click="openCreate">Add Subject</button></div>
<form v-if="data" class="en-card en-grid" @submit.prevent="apply"><label>Search code or name<input v-model.trim="filters.search" maxlength="100"></label><label>Program<select v-model="filters.course_id" @change="filters.curriculum_id='' "><option value="">All programs</option><option v-for="course in data.courses" :key="course.id" :value="course.id">{{ course.course_code }} — {{ course.course_name }}</option></select></label><label>Curriculum<select v-model="filters.curriculum_id"><option value="">All curricula</option><option v-for="curriculum in filteredCurricula" :key="curriculum.id" :value="curriculum.id">{{ curriculum.curriculum_code }} — {{ curriculum.curriculum_name }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Archived</option></select></label><button :disabled="busy" type="submit">Apply filters</button></form>
<section v-if="data && !data.subjects.data.length" class="en-card" role="status"><h2>No subjects have been configured for this curriculum.</h2><p>Create the first subject with its curriculum, year level, and semester assignment.</p><button @click="openCreate">Add Subject</button></section>
<div v-else-if="data" class="en-card en-table"><table class="subject-management-table"><thead><tr><th>Code</th><th>Subject Name</th><th>Units</th><th>Assigned Curriculum</th><th>Academic Context</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="subject in data.subjects.data" :key="subject.id"><td><strong>{{ subject.subject_code }}</strong></td><td>{{ subject.subject_name }}</td><td>{{ subject.units }}</td><td>{{ subject.curriculum?.course?.course_code }}<br>{{ subject.curriculum?.curriculum_code }}</td><td>Year {{ subject.year_level }} · {{ subject.semester?.semester_name }}</td><td><span class="en-badge" :data-status="subject.status">{{ subject.status==='inactive'?'Archived':label(subject.status) }}</span></td><td><div class="en-actions"><button @click="detail=subject">View</button><button @click="openEdit(subject)">Edit</button><button @click="openEdit(subject,true)">Assign to Curriculum</button><button class="en-secondary" @click="statusChange=subject">{{ subject.status==='active'?'Archive':'Reactivate' }}</button></div></td></tr></tbody></table><div class="en-actions"><button :disabled="busy||page<=1" @click="page--;load()">Previous</button><span>Page {{ data.subjects.current_page }} of {{ data.subjects.last_page }}</span><button :disabled="busy||page>=data.subjects.last_page" @click="page++;load()">Next</button></div></div>
<section v-if="data && groups.length" class="en-card"><h2>Program → Curriculum → Subjects</h2><div class="curriculum-groups"><article v-for="group in groups" :key="group.curriculum.id"><h3>{{ group.curriculum.course?.course_code }} · {{ group.curriculum.curriculum_name }}</h3><ul><li v-for="subject in group.subjects" :key="subject.id">Year {{ subject.year_level }} / {{ subject.semester?.semester_name }} — {{ subject.subject_code }} {{ subject.subject_name }}</li></ul></article></div></section>
<EnrollmentDialog v-if="form" labelledby="subject-form-title" :busy="busy" wide @cancel="form=null"><h2 id="subject-form-title">{{ form.id?(form.assignment?'Assign Subject to Curriculum':'Edit Subject'):'Add Subject' }}</h2><form @submit.prevent="save"><div class="en-grid"><label>Curriculum<select v-model="form.curriculum_id" required><option value="">Choose curriculum</option><option v-for="curriculum in curricula.filter(c=>c.status==='active'&&c.course?.status==='active')" :key="curriculum.id" :value="curriculum.id">{{ curriculum.course?.course_code }} · {{ curriculum.curriculum_code }} — {{ curriculum.curriculum_name }}</option></select></label><label>Semester<select v-model="form.semester_id" required><option value="">Choose semester</option><option v-for="semester in data.semesters.filter(s=>s.status==='active')" :key="semester.id" :value="semester.id">{{ semester.semester_name }}</option></select></label><label>Subject Code<input v-model.trim="form.subject_code" required maxlength="20" placeholder="BUS101"></label><label>Subject Name<input v-model.trim="form.subject_name" required maxlength="150"></label><label>Year Level<input v-model.number="form.year_level" type="number" min="1" :max="formCurriculum?.course?.years||20" required></label><label>Units<input v-model.number="form.units" type="number" min="0" max="999.9" step="0.1" required></label><label>Lecture Hours<input v-model.number="form.lecture_hours" type="number" min="0" max="40" required></label><label>Laboratory Hours<input v-model.number="form.laboratory_hours" type="number" min="0" max="40" required></label><label>Prerequisite<select v-model="form.prerequisite_subject_id"><option :value="null">No prerequisite</option><option v-for="subject in prerequisites" :key="subject.id" :value="subject.id">{{ subject.subject_code }} — {{ subject.subject_name }}</option></select></label><label v-if="!form.id">Status<select v-model="form.status"><option value="active">Active</option><option value="inactive">Archived</option></select></label></div><p v-if="form.id">Code, curriculum, semester, and year level cannot change after the subject is used in Enrollment, Scheduling, prerequisites, or grading.</p><div class="en-actions"><button :disabled="busy" type="submit">Save Subject</button><button class="en-secondary" :disabled="busy" type="button" @click="form=null">Cancel</button></div></form></EnrollmentDialog>
<EnrollmentDialog v-if="detail" labelledby="subject-detail-title" @cancel="detail=null"><h2 id="subject-detail-title">{{ detail.subject_code }} — {{ detail.subject_name }}</h2><dl><dt>Program and curriculum</dt><dd>{{ detail.curriculum?.course?.course_name }} · {{ detail.curriculum?.curriculum_name }}</dd><dt>Academic context</dt><dd>Year {{ detail.year_level }} · {{ detail.semester?.semester_name }}</dd><dt>Units and hours</dt><dd>{{ detail.units }} units · {{ detail.lecture_hours }} lecture · {{ detail.laboratory_hours }} laboratory</dd><dt>Prerequisite</dt><dd>{{ detail.prerequisite?.subject_code || 'None' }}</dd><dt>References</dt><dd>{{ detail.section_subjects_count }} section assignments · {{ detail.enrollment_subjects_count }} enrolled records</dd></dl><button @click="detail=null">Close</button></EnrollmentDialog>
<EnrollmentDialog v-if="statusChange" labelledby="subject-status-title" :busy="busy" @cancel="statusChange=null"><h2 id="subject-status-title">{{ statusChange.status==='active'?'Archive':'Reactivate' }} {{ statusChange.subject_code }}?</h2><p>Historical academic records remain unchanged. Archived subjects cannot be selected for new curriculum loads or schedules.</p><div class="en-actions"><button class="en-secondary" @click="statusChange=null">Cancel</button><button :disabled="busy" @click="changeStatus">Confirm</button></div></EnrollmentDialog>
</section></template>
